<template><div class="page"><div class="page-header"><div><div class="page-title">Webhook 通知</div><div class="page-subtitle">管理多个通知机器人，并按流程类型选择一个或多个推送目标</div></div><el-button type="primary" @click="openCreate">新增机器人</el-button></div>
<el-alert title="Webhook 地址加密保存且不会回显。每个机器人可订阅一种或多种流程，多个机器人订阅同一流程时会同时推送。" type="info" :closable="false" show-icon style="margin-bottom:16px"/>
<el-card><el-table v-loading="loading" :data="rows" empty-text="暂未配置通知机器人"><el-table-column prop="name" label="机器人名称" min-width="150"/><el-table-column label="平台" width="110"><template #default="{row}">{{providerLabel(row.provider)}}</template></el-table-column><el-table-column label="Webhook 地址" width="130"><template #default="{row}"><el-tag :type="row.webhookUrlConfigured?'success':'danger'">{{row.webhookUrlConfigured?'已安全配置':'未配置'}}</el-tag></template></el-table-column><el-table-column label="接收的通知" min-width="260"><template #default="{row}"><el-tag v-for="e in eventValues(row.eventTypes)" :key="e" class="event-tag">{{eventLabel(e)}}</el-tag></template></el-table-column><el-table-column label="状态" width="80"><template #default="{row}"><el-tag :type="row.enabled===1?'success':'info'">{{row.enabled===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="180"><template #default="{row}">{{formatDateTime(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="确定删除该机器人配置？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></el-card>
<el-dialog v-model="dialogVisible" :title="editingId?'编辑机器人':'新增机器人'" width="600px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="120px"><el-form-item label="机器人名称" prop="name"><el-input v-model="form.name" placeholder="例如：工程部核验群"/></el-form-item><el-form-item label="平台" prop="provider"><el-select v-model="form.provider" style="width:100%"><el-option label="企业微信" value="WECOM"/><el-option label="飞书" value="FEISHU"/><el-option label="钉钉" value="DINGTALK"/></el-select></el-form-item><el-form-item label="Webhook URL" :prop="editingId?undefined:'webhookUrl'"><el-input v-model="form.webhookUrl" type="password" show-password :placeholder="editingId?'留空保留原地址':urlPlaceholder"/></el-form-item><el-form-item label="流程通知" prop="events"><el-checkbox-group v-model="form.events" class="events"><el-checkbox v-for="e in eventOptions" :key="e.value" :label="e.value">{{e.label}}</el-checkbox></el-checkbox-group><div class="form-tip">勾选多个流程时，该机器人都会收到；同一流程也可配置多个机器人。</div></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,type FormInstance,type FormRules}from'element-plus';import{webhookApi,type WebhookConfig}from'@/api/webhook';import{formatDateTime}from'@/utils/format';
const eventOptions=[{value:'FIELD_VERIFICATION_CREATED_NEW_MERCHANT',label:'新商户开户—现场核验'},{value:'FIELD_VERIFICATION_CREATED_EXISTING_MERCHANT_ADD_STALL',label:'已有商户增加铺位—现场核验'},{value:'FIELD_VERIFICATION_CREATED_MERCHANT_EXIT',label:'已有商户撤柜—现场核验'},{value:'WORKFLOW_COMPLETED_NEW_MERCHANT',label:'新商户开户—流程完成'},{value:'WORKFLOW_COMPLETED_EXISTING_MERCHANT_ADD_STALL',label:'已有商户增加铺位—流程完成'},{value:'WORKFLOW_COMPLETED_MERCHANT_EXIT',label:'已有商户撤柜—流程完成'},{value:'ENERGY_ARREARS_NOTICE',label:'能源欠费账户通知'}],rows=ref<WebhookConfig[]>([]),loading=ref(false),saving=ref(false),dialogVisible=ref(false),editingId=ref<number>(),formRef=ref<FormInstance>();const form=reactive<{name:string;provider:'WECOM'|'FEISHU'|'DINGTALK';webhookUrl:string;enabled:boolean;events:string[]}>({name:'',provider:'WECOM',webhookUrl:'',enabled:true,events:[]});const rules:FormRules={name:[{required:true,message:'请输入机器人名称',trigger:'blur'}],provider:[{required:true,message:'请选择平台',trigger:'change'}],webhookUrl:[{required:true,message:'请输入 Webhook URL',trigger:'blur'}],events:[{type:'array',required:true,min:1,message:'请至少选择一种通知',trigger:'change'}]};const urlPlaceholder=computed(()=>form.provider==='WECOM'?'https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=...':form.provider==='FEISHU'?'https://open.feishu.cn/open-apis/bot/v2/hook/...':'https://oapi.dingtalk.com/robot/send?access_token=...');function providerLabel(v:string){return({WECOM:'企业微信',FEISHU:'飞书',DINGTALK:'钉钉'}as any)[v]||v}function eventValues(v:string){return v==='FIELD_VERIFICATION_CREATED'?eventOptions.filter(x=>x.value.startsWith('FIELD_VERIFICATION_CREATED_')).map(x=>x.value):(v||'').split(',').filter(Boolean)}function eventLabel(v:string){return eventOptions.find(x=>x.value===v)?.label||v}async function load(){loading.value=true;try{rows.value=await webhookApi.list()}finally{loading.value=false}}function openCreate(){editingId.value=undefined;Object.assign(form,{name:'',provider:'WECOM',webhookUrl:'',enabled:true,events:[]});dialogVisible.value=true}function openEdit(row:any){editingId.value=row.id;Object.assign(form,{name:row.name,provider:row.provider,webhookUrl:'',enabled:row.enabled===1,events:eventValues(row.eventTypes)});dialogVisible.value=true}async function save(){if(!await formRef.value?.validate())return;saving.value=true;try{const payload={name:form.name.trim(),provider:form.provider,webhookUrl:form.webhookUrl.trim()||undefined,enabled:form.enabled,eventTypes:form.events.join(',')};if(editingId.value)await webhookApi.update(editingId.value,payload);else await webhookApi.create(payload);ElMessage.success('机器人及通知配置已保存');dialogVisible.value=false;await load()}finally{saving.value=false}}async function remove(row:any){await webhookApi.delete(row.id);ElMessage.success('机器人配置已删除');await load()}onMounted(load)
eventOptions.push({value:'DATA_EXCEPTION_WARN',label:'异常中心—警告'},{value:'DATA_EXCEPTION_ERROR',label:'异常中心—错误'},{value:'DATA_EXCEPTION_CRITICAL',label:'异常中心—严重'},{value:'ENERGY_ACCOUNT_ANOMALY',label:'能源账户异动通知'})
eventOptions.push({value:'INSPECTION_TASK_DUE',label:'设备巡检—即将到期'},{value:'INSPECTION_TASK_OVERDUE',label:'设备巡检—已逾期'})
</script>
<style scoped>.page-subtitle{margin-top:5px;color:#909399;font-size:13px}.event-tag{margin:2px 5px 2px 0}.events{display:flex;flex-direction:column}.form-tip{font-size:12px;color:#909399;line-height:20px}@media(max-width:768px){.page-header{align-items:flex-start}.events :deep(.el-checkbox){white-space:normal;height:auto;margin:6px 0}}</style>
